/* trainer carousel */
var track=document.getElementById('trainerTrack'), dotsWrap=document.getElementById('tDots');
var cardW=292, visible=Math.max(1,Math.floor(track.clientWidth/cardW)||1);
var pages=Math.max(1,trainers.length-visible+1);
for(var i=0;i<pages;i++){var d=el('<span class="dot'+(i===0?' active':'')+'"></span>');
 d.addEventListener('click',(function(idx){return function(){track.scrollTo({left:idx*cardW,behavior:reduced?'auto':'smooth'});};})(i));
 dotsWrap.appendChild(d);}
function syncDots(){var idx=Math.round(track.scrollLeft/cardW);[].forEach.call(dotsWrap.children,function(d,i){d.classList.toggle('active',i===idx);});}
track.addEventListener('scroll',function(){clearTimeout(track._t);track._t=setTimeout(syncDots,80);});
document.getElementById('tPrev').addEventListener('click',function(){track.scrollBy({left:-cardW,behavior:reduced?'auto':'smooth'});});
document.getElementById('tNext').addEventListener('click',function(){track.scrollBy({left:cardW,behavior:reduced?'auto':'smooth'});});

/* testimonial carousel */
var qTrack=document.getElementById('tstTrack'), qDots=document.getElementById('qDots'), qi=0, qTimer;
testis.forEach(function(t,i){
 var stars=Array(5).fill(0).map(function(_,s){return icon('star');}).join('');
 qTrack.appendChild(el('<div class="tst-item'+(i===0?' active':'')+'"><div class="tst-card"><div class="tst-stars">'+
  Array(t.rating).fill(icon('star')).join('')+'</div><p>'+t.text+'</p><div class="tst-who">'+
  '<div class="tst-avatar">'+t.name.split(' ').map(function(n){return n[0];}).join('')+'</div>'+
  '<div style="text-align:left"><b>'+t.name+'</b><span>Verified member</span></div></div></div></div>'));
 var d=el('<span class="dot'+(i===0?' active':'')+'"></span>'); d.addEventListener('click',function(){goQ(i);}); qDots.appendChild(d);
});
function goQ(n){qi=(n+testis.length)%testis.length;
 [].forEach.call(qTrack.children,function(c,i){c.classList.toggle('active',i===qi);});
 [].forEach.call(qDots.children,function(c,i){c.classList.toggle('active',i===qi);});}
function nextQ(){goQ(qi+1);}
function startQ(){if(!reduced){qTimer=setInterval(nextQ,5500);}}
function stopQ(){clearInterval(qTimer);}
startQ();
document.getElementById('qPrev').addEventListener('click',function(){stopQ();goQ(qi-1);startQ();});
document.getElementById('qNext').addEventListener('click',function(){stopQ();goQ(qi+1);startQ();});
document.getElementById('tstWrap').addEventListener('mouseenter',stopQ);
document.getElementById('tstWrap').addEventListener('mouseleave',startQ);

/* lightbox */
var lb=document.getElementById('lightbox'), lbBox=document.getElementById('lbBox');
gg.addEventListener('click',function(e){
 var item=e.target.closest('.gal-item'); if(!item)return;
 var bgStyle=item.querySelector('.gal-bg').getAttribute('style');
 lbBox.setAttribute('style',bgStyle);
 var existing=lbBox.querySelector('.lb-label'); if(existing)existing.remove();
 lbBox.appendChild(el('<span class="lb-label" style="position:absolute;bottom:18px;left:20px;font-weight:700">'+item.dataset.label+'</span>'));
 lb.classList.add('open');
});
